        int left = 0, right = array.length;
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (array[mid] <= value) left = mid + 1;
            else right = mid;
        }
        return left;
    }

    static int query(int[] bit, int index) {
        int result = 0;
        while (index > 0) {
            result = Math.max(result, bit[index]);
            index -= index & -index;
        }
        return result;
    }

    static void update(int[] bit, int index, int value) {
        while (index < bit.length) {
            bit[index] = Math.max(bit[index], value);
            index += index & -index;
        }
    }

