        for (int i = 0; i < m; i++) {
            adj[u[i]][cursor[u[i]]++] = v[i];
            adj[v[i]][cursor[v[i]]++] = u[i];
        }

        for (int i = 0; i < n; i++) {
            Arrays.sort(adj[i]);
        }

