        int[] from = new int[edgeCount];
        int[] position = new int[edgeCount];
        long[] order = new long[edgeCount];

        int id = 0;
        for (int a = 0; a < n; a++) {
            for (int p = 0; p < adj[a].length; p++) {
                int b = adj[a][p];
                from[id] = a;
                position[id] = p;
                long sortKey = ((long) (200001 - (a + b)) << 32) | (id & 0xffffffffL);
                order[id] = sortKey;
                id++;
            }
        }

        Arrays.sort(order);

        int[] answer = new int[n];
        Arrays.fill(answer, 1);

        for (long key : order) {
            int edgeId = (int) key;
            int a = from[edgeId];
            int p = position[edgeId];
            int b = adj[a][p];

            int firstGreater = upperBound(adj[b], a);
            int countGreater = adj[b].length - firstGreater;
            int bestContinuation = query(bit[b], countGreater);

            int length = Math.max(2, bestContinuation + 1);
            answer[a] = Math.max(answer[a], length);

            int reversedPosition = adj[a].length - p;
            update(bit[a], reversedPosition, length);
        }

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) output.append(' ');
            output.append(answer[i]);
        }
        System.out.println(output);
    }
}
